create table if not exists datasource (  id varchar(64) primary key,  tenant_id varchar(64) not null references tenant(id),  type varchar(64) not null,  name varchar(128) not null,  status varchar(32) not null default 'inactive',  config_json jsonb not null default '{}'::jsonb,  last_sync_at timestamptz,  created_at timestamptz not null default now(),  updated_at timestamptz not null default now());create table if not exists datasource_sync_run (  id varchar(64) primary key,  tenant_id varchar(64) not null references tenant(id),  datasource_id varchar(64) not null references datasource(id) on delete cascade,  sync_type varchar(64) not null default 'manual',  status varchar(32) not null default 'running',  message text,  stats_json jsonb not null default '{}'::jsonb,  started_at timestamptz not null default now(),  finished_at timestamptz,  created_by varchar(64));create table if not exists asset (  id varchar(64) primary key,  tenant_id varchar(64) not null references tenant(id),  asset_type varchar(64) not null,  name varchar(256) not null,  display_name varchar(256),  source varchar(64) not null default 'manual',  source_id varchar(256),  env varchar(64),  ip varchar(64),  tags jsonb not null default '{}'::jsonb,  status varchar(32) not null default 'active',  created_at timestamptz not null default now(),  updated_at timestamptz not null default now());create table if not exists asset_relation (  id varchar(64) primary key,  tenant_id varchar(64) not null references tenant(id),  from_asset_id varchar(64) not null references asset(id) on delete cascade,  to_asset_id varchar(64) not null references asset(id) on delete cascade,  relation_type varchar(64) not null,  confidence numeric(5,4) not null default 1.0,  source varchar(64) not null default 'manual',  created_at timestamptz not null default now());alter table datasource add column if not exists last_sync_at timestamptz;create index if not exists idx_asset_tenant_type on asset(tenant_id, asset_type);create unique index if not exists uq_asset_tenant_source_source_id  on asset(tenant_id, source, source_id) where source_id is not null;create index if not exists idx_datasource_sync_run_ds_started  on datasource_sync_run(datasource_id, started_at desc);
